"""Fichas editoriais baseadas no recorte documental do MVP; sem chamada a LLM."""
import json


def executar(base):
    import streamlit as st
    from .dashboard import t,cabecalho,carregar_pmma,carregar_sibal,cobertura,erro,ir,PDF
    cabecalho(t('Investigations','Investigações'),t('Purpose, evidence and limitations — connected to the data.','Objetivo, evidências e limitações — conectados aos dados.'))
    st.caption(t('Editorial summaries for the sources loaded in this MVP. They are not generated by an LLM and do not describe the full scope of each investigation.',
                 'Resumos editoriais das fontes carregadas neste MVP. Não são gerados por LLM nem descrevem todo o escopo de cada investigação.'))
    escolha=st.selectbox(t('Investigation','Investigação'),['BASS-II','BASS','Saffire'],key='ff_investigation')
    if escolha in ('BASS-II','BASS'):
        try:
            ss=carregar_sibal(base)
            ss=[r for r in ss if r['investigacao_id']==('PSI-25' if escolha=='BASS-II' else 'PSI-26')]
            ps,_=carregar_pmma(base) if escolha=='BASS-II' else ([],{})
        except Exception as exc:erro(exc);return
        st.subheader(escolha)
        st.write(t('Focus of this collection: flame spread over solid fuels in microgravity, with published airflow and oxygen conditions.',
                   'Foco desta coleção: propagação de chamas sobre combustíveis sólidos em microgravidade, com condições publicadas de fluxo e oxigênio.'))
        st.write(t('Materials in the loaded tables: ','Materiais nas tabelas carregadas: ')+('PMMA; SIBAL (cotton–fiberglass).' if escolha=='BASS-II' else 'SIBAL (cotton–fiberglass).'))
        st.caption(t('SIBAL: cotton and fiberglass composite. PMMA: polymethyl methacrylate.','SIBAL: composto de algodão e fibra de vidro. PMMA: polimetilmetacrilato.'))
        a,b=st.columns(2)
        with a:st.metric(t('SIBAL records in this collection','Registros SIBAL nesta coleção'),len(ss))
        with b:st.metric(t('PMMA tests in this collection','Testes PMMA nesta coleção'),len({r['teste_id'] for r in ps}) if ps else '—')
        st.markdown('**'+t('What is available','O que está disponível')+'**')
        st.write(t('SIBAL Table 7.1: sample width, airflow, oxygen and observations. Flame-spread rates are not supplied by this table.',
                   'SIBAL, Tabela 7.1: largura da amostra, escoamento, oxigênio e observações. Esta tabela não fornece taxas de propagação.'))
        if ps:
            st.write(t('PMMA Table 5.1: thickness, width, burning faces and opposed-flow spread measurements. Conditions within one test are not independent replicates.',
                       'PMMA, Tabela 5.1: espessura, largura, faces em queima e medições de propagação em fluxo oposto. Condições de um teste não são réplicas independentes.'))
        st.markdown('**'+t('Evidence cards','Cartões de evidência')+'**')
        cards=[]
        if ps:
            missing=[r for r in ps if r['propagacao_mm_s'] is None]
            nomes=sorted({r['teste'] for r in missing})
            cards.append({'title':t('Untracked spread is not zero spread','Propagação não rastreada não é propagação zero'),
                'statement':t(f'{len(missing)} conditions have no numeric spread value; tests: {", ".join(nomes)}.',f'{len(missing)} condições não têm valor numérico de propagação; testes: {", ".join(nomes)}.'),
                'source':{'document':'NASA/TM-20210011385','table':'5.1','physical_page':65,'printed_page':57},
                'record_ids':[r['condicao_id'] for r in missing]})
        caveats=[r for r in ss if r['oxigenio_nota_b']]
        reused=[r for r in ss if r['reutilizacao_relata'] is True]
        cards.append({'title':t('Oxygen caveats and sample reuse','Ressalvas de oxigênio e reutilização'),
            'statement':t(f'{len(caveats)} records carry note b; {len(reused)} explicitly report reuse in the selected collection. Missing reuse information does not prove a new sample.',
                          f'{len(caveats)} registros têm nota b; {len(reused)} relatam reutilização na coleção selecionada. Reutilização não informada não comprova amostra nova.'),
            'source':{'document':'NASA/TM-20210011385','table':'7.1','physical_page':104,'printed_page':96},
            'oxygen_caveat_ids':[r['registro_id'] for r in caveats], 'reuse_ids':[r['registro_id'] for r in reused]})
        for card in cards:
            with st.container(border=True):
                st.markdown('**'+card['title']+'**');st.write(card['statement'])
                page=card['source']['physical_page']
                st.markdown(f'[{t("Source: NASA report, physical page","Fonte: relatório NASA, página física")} {page}]({PDF}#page={page})')
                with st.expander(t('Record references','Referências dos registros')):st.json(card)
        st.caption(t('These are observations about the loaded records, not material safety classifications. Check apparatus, pressure and measurement method before comparing to other studies.',
                     'São observações sobre os registros carregados, não classificações de segurança dos materiais. Confira aparato, pressão e método antes de comparar com outros estudos.'))
        a,b=st.columns(2)
        with a:st.button(t('Open SIBAL explorer','Abrir explorador SIBAL'),key='inv_sibal',on_click=ir,args=('sibal',))
        if ps:
            with b:st.button(t('Open PMMA explorer','Abrir explorador PMMA'),key='inv_pmma',on_click=ir,args=('pmma',))
        st.download_button(t('Export evidence cards (JSON)','Exportar cartões de evidência (JSON)'),json.dumps({'investigation':escolha,'type':'editorial_summary','cards':cards,'llm_generated':False},ensure_ascii=False,indent=2),file_name='firefly_'+escolha+'_evidence.json',mime='application/json')
    else:
        try:rs,_=cobertura(base)
        except Exception as exc:erro(exc);return
        st.subheader('Saffire')
        st.write(t('The loaded sources describe large-scale fire experiments aboard the uncrewed Cygnus spacecraft. Keep Saffire-I, II and III distinct when reading methods and results.',
                   'As fontes carregadas descrevem experimentos de incêndio em maior escala na espaçonave Cygnus não tripulada. Distinga Saffire-I, II e III ao ler métodos e resultados.'))
        st.write(t('The article discusses cotton–fiberglass fabric and includes a PMMA slab in Saffire-II. Here these are documentary findings; they are not an imported raw telemetry dataset.',
                   'O artigo discute tecido de algodão e fibra de vidro e inclui uma placa de PMMA em Saffire-II. Aqui são achados documentais, não um conjunto importado de telemetria bruta.'))
        mapa={r['recorte_id']:r for r in rs}
        casos=[('SAFFIRE_ARTIGO_P08_37',t('Saffire-III: published result','Saffire-III: resultado publicado'),t('The article reports 25 cm/s airflow and a quasi-steady spread rate of 2.32 mm/s. These are different quantities and units.',
                'O artigo relata escoamento de 25 cm/s e propagação quase estacionária de 2,32 mm/s. São grandezas e unidades diferentes.')),
               ('SAFFIRE_DOD_P01_24',t('Keep the documentary discrepancy visible','Preserve a divergência documental'),t('The DoD describes 30 cm/s for Saffire-III in prospective language; the article reports 25 cm/s. The loaded sources do not establish why the descriptions differ.',
                'O DoD descreve 30 cm/s para Saffire-III em linguagem prospectiva; o artigo relata 25 cm/s. As fontes carregadas não estabelecem por que as descrições diferem.'))]
        for ident,title,claim in casos:
            if ident not in mapa:
                st.warning(t('Required source excerpt unavailable: ','Recorte necessário indisponível: ')+ident);continue
            r=mapa[ident]
            with st.container(border=True):
                st.markdown('**'+title+'**');st.write(claim)
                for f in r['fontes']:
                    st.caption(f.get('titulo_documento',f['documento_id'])+' · '+t('physical page ','página física ')+str(f['pagina_fisica']))
                with st.expander(t('Read original evidence','Ler evidência original')):
                    st.text(r['texto_para_busca']);st.code(ident)
        st.caption(t('Editorial interpretation: do not combine different missions or treat planned and reported settings as identical. The combustion guide is background material, not another experiment.',
                     'Interpretação editorial: não combine missões diferentes nem trate configurações planejadas e relatadas como idênticas. O guia de combustão é contexto, não outro experimento.'))
        st.markdown('[Flame spread: Effects of microgravity and scale · DOI](https://doi.org/10.1016/j.combustflame.2018.10.012)')
        st.button(t('Open evidence search','Abrir busca de evidências'),key='inv_search',on_click=ir,args=('search',))
